def _backfill_locations() -> None:
    """Recover eBird's privacy flag from archived responses, so no API calls are needed.

    Later responses win. Locations with no recoverable flag get no row, and the API
    treats those as private.
    """
    bind = op.get_bind()
    raw = sa.table("raw_responses", sa.column("id", sa.Integer), sa.column("payload", sa.JSON))
    found = {}
    for (payload,) in bind.execute(sa.select(raw.c.payload).order_by(raw.c.id)):
        if not isinstance(payload, list):
            continue
        for item in payload:
            if not isinstance(item, dict) or not item.get("locId"):
                continue
            found[item["locId"]] = {
                "loc_id": item["locId"],
                "is_private": item.get("locationPrivate") is not False,
                "lat": item.get("lat"),
                "lng": item.get("lng"),
            }
    if found:
        locations = sa.table(
            "locations",
            sa.column("loc_id", sa.String),
            sa.column("is_private", sa.Boolean),
            sa.column("lat", sa.Float),
            sa.column("lng", sa.Float),
        )
        op.bulk_insert(locations, list(found.values()))
